import React from "react";
import { Link, useLocation } from "react-router-dom";
import { motion } from "framer-motion";

const Navbar = () => {
  const location = useLocation();
  const links = [
    { name: "Home", path: "/" },
    { name: "Interview", path: "/interview" },
    { name: "Feedback", path: "/feedback" },
  ];

  return (
    <motion.nav
      initial={{ y: -50, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      className="bg-blue-950/90 backdrop-blur-lg sticky top-0 z-50 shadow-md"
    >
      <div className="max-w-7xl mx-auto flex items-center justify-between p-4">
        <Link to="/" className="text-2xl font-bold text-blue-400">
          AI Interview Coach
        </Link>

        <div className="flex space-x-6">
          {links.map((link) => (
            <Link
              key={link.name}
              to={link.path}
              className={`transition-colors ${
                location.pathname === link.path
                  ? "text-blue-400 font-semibold"
                  : "text-gray-300 hover:text-blue-400"
              }`}
            >
              {link.name}
            </Link>
          ))}
        </div>

        <div className="flex space-x-3">
          <Link
            to="/login"
            className="px-4 py-2 bg-blue-500 rounded-md hover:bg-blue-600 transition-all"
          >
            Login
          </Link>
          <Link
            to="/signup"
            className="px-4 py-2 border border-blue-500 text-blue-400 rounded-md hover:bg-blue-500 hover:text-white transition-all"
          >
            Sign Up
          </Link>
        </div>
      </div>
    </motion.nav>
  );
};

export default Navbar;
